//! The task texts of the course, each paired with the solution that answers it.
//!
//! A task copied word for word must land on its own solution without guessing
//! from a few keywords. Anything phrased differently still goes through the
//! ordinary parser and templates.

use std::sync::OnceLock;

/// What answers a book task.
#[derive(Clone, Copy)]
pub enum Solution {
    /// The lesson of the book that teaches this task, as an index into
    /// `lessons::ALL`.
    Lesson(usize),
    /// A short task the templates already understand. Used only when the
    /// wording of the book task itself is not understood, so a task that
    /// names a button keeps its button.
    Seed(&'static str),
}

